from string import ascii_lowercase, ascii_uppercase, digits
import secrets
safe_punctuation = '`*_-.'

def generate_safe_punctuation():
    return safe_punctuation

def generate_password(length):
    required_types = [ascii_lowercase, ascii_uppercase, digits, safe_punctuation]
    password_characters = []
    for _type in required_types:
        password_characters.extend(_type)

    if len(password_characters) < length:
        password_characters.append(secrets.choice(safe_punctuation))

    return ''.join(secrets.choice(password_characters) for _ in range(length))

# Example usage:
print(generate_password(12))
